      "question": "Bu klinik tabloyu en iyi açıklayan embriyolojik gelişim bozukluğu hangisidir?",
      "explanation": "Yenidoğanda doğumdan hemen sonra solunum sıkıntısı, çökük abdomen, tek hemitoraksta barsak ansları ve mediastinal itilme abdominal içeriğin toraks boşluğuna geçtiğini gösterir. Bu düzen en iyi posterolateral diyafram açıklığıyla, yani pleuroperitoneal kanalların membranlarla kapatılmasının tamamlanmamasıyla açıklanır. Ön karın duvarı kıvrım kusuru, trakeoözofageal ayrım bozukluğu veya santral tendon katkı problemi bu grafi ve muayene bulgularını aynı şekilde açıklamaz.",
      "pearls": [
        "Yenidoğanda toraksta barsak ansları ve çökük abdomen birlikteyse posterolateral diyafram kapanma kusuru, mekanizma olarak pleuroperitoneal membranlar düşünülür."
      ],
      "optionComparison": {
        "Pleuroperitoneal membranların kapanmasının tamamlanmaması": "Doğru. Posterolateral diyafram açıklığı ve abdominal organların toraksa geçmesi, plevral ve peritoneal boşluklar arasındaki kanalın kapanmasının tamamlanmamasıyla açıklanır. Yenidoğanda solunum sıkıntısı, bağırsak anslarının toraksta görülmesi ve karında çöküklük bu mekanizmayla uyumludur.",
        "Septum transversumun ön bölgeye katkı verememesi": "Septum transversum diyaframın santral tendonuna önemli katkı verir. Ön yerleşimli büyük gelişim kusurları açısından akla gelebilir. Ancak bu vakada bulgu posterolateral toraks içine abdominal içerik geçişidir; santral tendon eksikliği ön planda değildir.",
        "Dorsal mezenterin özofagus çevresinde kaybolması": "Dorsal mezenter özofagus ve bağırsakların asılmasıyla ilişkilidir. Diyafram çevresi anatomisi nedeniyle çeldirici olabilir. Fakat posterolateral diyafram açıklığını ve barsakların toraksa geçişini açıklayan temel olay plevroperitoneal kanal kapanmasıdır.",
        "Lateral vücut kıvrımlarının ventral hatta birleşememesi": "Lateral vücut kıvrımlarının ventral hatta birleşememesi omfalosel veya gastroşizis gibi ön karın duvarı anomalileriyle ilişkilidir. Abdominal organların yer değiştirmesi nedeniyle akla gelebilir. Bu vakada organlar dış karın duvarından değil, toraks boşluğuna geçmiştir.",
        "Trakeoözofageal septumun ön bağırsağı ayıramaması": "Trakeoözofageal septumun ön bağırsağı ayıramaması trakeoözofageal fistül veya özofagus atrezisiyle ilişkilidir. Yenidoğanda beslenme-solunum sorunu yapabilir. Ancak burada ilk bulgu toraksta barsak ansları ve mediastinal yer değiştirmedir; ön bağırsak lümen ayrımı kusuru verilmemiştir."
      },
