      "question": "Bu lezyonu en iyi açıklayan gelişimsel kalıntı hangisidir?",
      "explanation": "Orta hatta hyoid komşuluğunda bulunan ve yutkunma ile dil hareketi sırasında yukarı yer değiştiren kistik lezyon, tiroid primordiyumunun iniş yolu boyunca kalan kanal artığını destekler. Tiroid dokusunun normal yerinde görülmesi, bunun ektopik tek tiroid dokusu olmadığını gösterir. Lateral boyun yarık/sinüs kalıntıları, ultimobrankiyal katkı veya timus iniş yolu bu orta hat hareket paternini daha iyi açıklamaz.",
      "pearls": [
        "Orta hat boyun kisti yutkunma ve dil hareketiyle yukarı gidiyorsa tiroid iniş yolu kalıntısı düşünülür; lateral brankiyal kistler SCM ön kenarında beklenir."
      ],
      "optionComparison": {
        "Tiroglossal kanal kalıntısı": "Doğru. Orta hatta hyoid komşuluğunda yer alan, yutkunma ve dil hareketiyle hareket eden kistik yapı, tiroid primordiyumunun iniş yolu boyunca kalan kanal artığıyla açıklanır. Normal tiroid dokusunun yerinde izlenmesi bu kistin ayrı bir gelişimsel kalıntı olduğunu destekler.",
        "İkinci brankiyal yarık kalıntısı": "İkinci brankiyal yarık kalıntıları genellikle sternokleidomastoid kas ön kenarı boyunca lateral boyun kisti veya fistülü şeklinde ortaya çıkar. Boyun kisti nedeniyle çeldirici olabilir. Ancak vakada şişlik lateral değil orta hatta ve dil-yutkunma hareketleriyle belirgin yer değiştirmektedir.",
        "Ultimobrankiyal cisim kalıntısı": "Ultimobrankiyal cisim, tiroidin parafoliküler C hücreleriyle ilişkilidir. Tiroid gelişimi bağlamında akla gelebilir. Fakat yüzeyel orta hat kistik yol kalıntısını değil, tiroid içi hücre katkısını açıklar.",
        "Servikal sinüs kalıcılığı": "Servikal sinüs kalıcılığı brankiyal ark-yarık gelişimiyle ilişkili lateral boyun anomalilerine yol açabilir. Kistik boyun lezyonu nedeniyle çeldiricidir. Bu vakadaki hyoid komşuluğu ve dil hareketiyle yer değiştirme orta hat migrasyon yolunu destekler.",
        "Ektopik timus dokusu": "Ektopik timus dokusu üçüncü faringeal kese kökenli iniş yolu boyunca boyunda kitle oluşturabilir. Boyunda gelişimsel doku bulunması nedeniyle akla gelebilir. Ancak timus iniş yolu lateral/alt boyun yönelimlidir; vakada normal tiroid dokusu ve orta hat hyoid komşuluğunda hareketli kist ön plandadır."
      },
