      "Apokrin ter bezi": "Apokrin ter bezleri daha geniş lümenlidir ve genellikle kıl folikülüyle ilişkili bölgelerde bulunur. Terleme ve deri eklentisi bağlamı nedeniyle çeldiricidir. Bu örnekte küçük lümenli sık kıvrımlı tübüller ve yüzeye açılan kanal düzeni apokrin bezden çok farklıdır.",
