      "question": "Bu mikroskobik bulgular hipofizin hangi bölümüyle en uyumludur?",
      "explanation": "Sellar cerrahi sonrası gelişen poliüri ve düşük idrar osmolaritesi, ADH depolanma/salınma hattının etkilenebileceğini gösterir. Doku kesitinde endokrin hücre kordonları yerine unmyelinize akson ağı, pituicyte benzeri destek hücreleri ve aksonal genişlemeler görülmesi nörohipofiz arka lobuna özgü organizasyonu destekler. Bu nedenle bulgular pars nervosa ile en iyi açıklanır; adenohipofiz bölümleri hücre kordonu-sinüzoid düzeniyle beklenirdi.",
