        "Pars intermedia": "Pars intermedia insanlarda ince bir ara bölge olarak kalır ve kolloid benzeri kistler içerebilir. Hipofiz kesitinde çeldirici olabilir. Bu vakada verilen klinik su dengesi bozukluğu ve aksonal doku paterni ara lobdan çok arka lob bileşenini destekler.",
        "Pars tuberalis": "Pars tuberalis infundibulum çevresinde yer alan adenohipofiz uzantısıdır ve küçük endokrin hücre kümeleri içerir. Sap çevresi yerleşim nedeniyle akla gelebilir. Ancak mikroskopide belirgin sinir lifleri ve aksonal genişlemeler tanımlanması bu seçeneği geri plana iter.",
        "Pars nervosa": "Doğru. Unmyelinize aksonların oluşturduğu lif ağı, pituicyte benzeri destek hücreleri ve aksonal hormon depolama genişlemeleri nörohipofizin arka lob dokusuyla uyumludur. Cerrahi sonrası poliüri ve düşük idrar osmolaritesi de ADH salınım hattının etkilenmesini klinik olarak destekler.",
        "Median eminens": "Median eminens hipotalamusun nörohemal bölgesidir ve portal damar sistemiyle adenohipofiz regülasyonuna katılır. Su dengesi ve hipotalamo-hipofizer bağlam nedeniyle çeldiricidir. Fakat doku örneği sellar arka lob paterninde olup pars nervosa mikroskopik özellikleri taşır."
