        "Çubuk fotoreseptör hücresi": "Düşük ışıkta görme kaybı ve periferik dış retina tutulumunda esas işlevsel hücre çubuk fotoreseptördür. Dış nükleer tabakada fotoreseptör çekirdeklerinin seyrelmesi ve dış segment düzensizliği, ışığı nöral sinyale çeviren bu hücre grubunun kaybıyla ilişkilidir. Renkli görmenin korunması da koni ağırlıklı bir sürecin ön planda olmadığını destekler.",
