        "Bipolar ara nöron": "Bipolar hücreler fotoreseptörlerden gelen sinyali ganglion hücrelerine aktaran ara nöronlardır. İç nükleer tabaka etkilenimi veya sinaptik iletim katmanı vurgulansaydı akla gelebilirdi. Burada primer sorun dış segment ve dış nükleer tabaka düzenindedir.",
        "Retinal pigment epitel hücresi": "Retinal pigment epiteli fotoreseptör dış segmentlerinin fagositozu ve görsel döngünün desteklenmesi için gereklidir. Pigment granülleri, Bruch membranı ve destek hücre katmanı baskın olsaydı bu seçenek daha güçlü olurdu. Ancak verilen klinik hedef doğrudan düşük ışıkta çalışan fotoreseptör popülasyonudur."
