        "Dorsal ektodermde Wnt7a sinyalinin kaybı": "Wnt7a dorsal-ventral ekstremite kimliğinin kurulmasına katkı sağlar. El sırtı/avuç içi kimliği bozukluğu veya tırnak-palma yüzeyi düzeni vurgulansaydı bu seçenek daha güçlü olurdu. Vakadaki temel sorun radial-ulnar/ön-arka parmak paternidir.",
