        "Duktus arteriozus düz kasının kasılamaması": "Duktus arteriozusun açık kalması sürekli üfürüm ve sistemik-pulmoner şantla ilişkilidir. Neonatal üfürüm nedeniyle çeldirici olabilir. Fakat ekokardiyografide ortak atriyoventriküler geçiş ve kapak düzeyi septal açıklık tariflenmesi PDA mekanizmasını açıklamaz.",
        "Endokardiyal yastıkların orta hatta birleşememesi": "Endokardiyal yastıklar atriyoventriküler kanalın bölünmesi, AV kapakların oluşumu ve atriyal-ventriküler septumların membranöz bölgeleri için kritik rol oynar. Ortak AV geçiş ve kapak düzeyinde septal açıklık, bu yapıların birleşme kusuruyla açıklanır. Klinik bulgudaki beslenme sırasında yorulma ve ekokardiyografi paterni bu mekanizmayı destekler.",
