        "Altıncı aortik arkın pulmoner segmente dönüşememesi": "Altıncı aortik ark pulmoner arterlerin ve duktus arteriozusun gelişimiyle ilişkilidir. Pulmoner damar anomalileri veya duktal yapı sorulsa bu seçenek değerlendirilebilirdi. Bu vakadaki temel bulgu atriyoventriküler septasyon düzeyindedir, aortik ark türevlerinden kaynaklanmaz."
