        "Kalp kası": "Kalp kası da çizgilenme taşır, fakat hücreleri dallanır, genellikle santral çekirdeklidir ve interkalar disklerle birbirine bağlanır. Bu vakada periferik çok çekirdekli uzun lifler ve düzenli demet yapısı verildiği için miyokard dokusu değil somatik çizgili kas dokusu değerlendirilir.",
