        "Üreter tomurcuğunun metanefrik mezenkimi indükleyememesi": "Üreter tomurcuğu ile metanefrik mezenkim arasındaki karşılıklı indüksiyon böbrek parankimi ve toplayıcı sistem gelişimi için gereklidir. Bu etkileşim kurulamazsa renal agenezi veya ağır hipoplazi beklenir; vakada ise iki tarafta doku varlığı ve orta hatta birleşme tarif edilmiştir.",
        "Mezonefrik kanalın kalıcı genital kanallara dönüşememesi": "Mezonefrik kanal erkek iç genital sisteminin epididim, vaz deferens ve seminal vezikül gibi türevlerine katkı verir. Prenatal görüntülemedeki birleşmiş böbrek alt kutupları genital kanal gelişiminden değil, metanefrik böbreğin yer değiştirme sürecinden kaynaklanır.",
        "Kloakal membranın karın ön duvarıyla ayrımının bozulması": "Kloakal membran ve ventral abdominal duvar gelişim kusurları alt karın duvarı, mesane ve dış ortam ilişkisini etkileyen açıklıklarla sonuçlanabilir. Bu vakada karın duvarı açıklığı veya mesane dışa açılımı değil, retroperitoneal böbrek dokularının orta hatta birleşmesi gösterilmiştir.",
