      "Dorsal kök ganglion nöronu": "Dorsal kök ganglion nöronları periferik ganglionda psödounipolar gövdeler ve çevresinde satellit hücre halkasıyla tanınır. Vaka verisinde ganglion kapsülü veya satellit hücre düzeni yoktur; katmanlı serebellar korteksteki ara sıra büyük nöronlar farklı bir merkezi sinir sistemi hücresini gösterir."
