        "Palatin çıkıntıların orta hatta birleşememesi": "Palatin çıkıntıların birleşme kusuru sekonder damak yarığına yol açar ve beslenirken burundan sıvı gelmesi gibi oral-nazal açıklık bulguları daha belirgin olur. Bu vakada yarık üst dudak ve burun tabanı düzeyindedir, sekonder damak muayenesinin korunmuş olması primer yüz çıkıntısı birleşme kusurunu daha iyi açıklar.",
