        "Proliferasyon zonu": "Bu yanıt, büyüme plağında uzun eksen boyunca paralel kolonlar oluşturan yassı kondrositlerin izlenmesiyle uyumludur. Proliferasyon zonunda kondrositler mitotik olarak çoğalır ve endokondral kemikleşmede uzunlamasına büyümenin hücresel düzenini oluşturur; hipertrofi zonundan hücrelerin şişmemiş, kolonlar halinde sık dizilmiş olmasıyla ayrılır.",
