        "Odontoblast": "Odontoblast dentin matriksini üretir ve dental papilla mezenşiminden gelişir. Bu vakada dentin kalınlığı korunmuş, asıl bozukluk dış parlak mine tabakasında verilmiştir; dentin kusuru olsaydı pulpa çevresinde dentin yapımı ve dentin tübülleri üzerinden ayrım yapılırdı.",
