        "Osteoblast": "Osteoblast kemik matriksini yapan hücredir ve alveoler kemik dahil iskelet dokusunun yapımıyla ilişkilidir. Bu vakada çene kemiği mineralizasyonu veya trabeküler kemik yapımı değil, diş kronunun mine tabakası incelenmektedir.",
