      "Hertwig epitel kılıfı hücresi": "Hertwig epitel kılıfı kök şekillenmesini ve kök dentini gelişiminin yönlendirilmesini sağlar. Vaka kron yüzeyindeki mine tabakasıyla sınırlıdır; kök morfolojisi veya kök gelişim bozukluğu verilmediği için bu yapı temel açıklama değildir."
