        "Ductus arteriosus düz kasının oksijen artışıyla kasılması": "Ductus arteriosus kapanması doğum sonrası oksijen artışı ve prostaglandin azalmasıyla ilişkili ayrı bir fetal şant kapanma olayıdır. Bu mekanizma pulmoner arter-aorta bağlantısını ilgilendirir; vakadaki sağ-sol atriyal şant penceresi için atriyal basınç farkı ve septal kapak ilişkisi gerekir.",
        "Ductus venosusun fibröz bağa dönüşmesi": "Ductus venosus fetal dönemde umbilikal venden gelen kanın karaciğeri kısmen bypass ederek inferior vena kavaya yönelmesini sağlar. Doğum sonrası kapanması karaciğer içi venöz yolun kapanmasıdır; atriyal septumdaki kapaklı açıklığın fonksiyonel kapanmasını açıklamaz.",
