        "Mezonefrik kanalların testosteron etkisiyle persiste kalması": "Mezonefrik kanallar erkek iç genital sisteminin epididimis, ductus deferens ve seminal vezikül gibi yapılarına katkı verir. Hastada kadın iç genital kanalında iki ayrı uterin boşluk ve fundal şekil bozukluğu vardır; bu bulgular Wolff kanal persistanlığından çok Müller kanal füzyon basamağını ilgilendirir.",
        "Ürogenital sinüs kökenli vajinal plağın kanalize olmaması": "Vajinal plak kanalizasyon kusuru dışa akım engeli, hematokolpos ve siklik ağrı gibi alt genital kanal bulgularıyla öne çıkar. Bu hastada servikal ve vajinal çıkış açıklığı değerlendirmede korunmuş, sorun uterin fundus ve kavite mimarisinde saptanmıştır; bu nedenle kanalizasyon basamağı hedef mekanizma değildir.",
        "Gubernakulumun uterin iniş sırasında yönlendirme görevini tamamlayamaması": "Gubernakulum özellikle gonadların pozisyonlanması ve kadınlarda ligamentum ovarii proprium ile ligamentum teres uteri ilişkisi açısından önem taşır. Vaka verisi gonad inişi veya ligament yerleşimi değil, iki paramezonefrik kanalın orta hatta uterin gövde oluşturma sürecindeki birleşme kusurunu göstermektedir."
