      "Primer adrenal kortizol sentez azalmasına bağlı ACTH artışı": "Primer adrenal kortizol sentez azalması ACTH artışı ve glukokortikoid eksikliğiyle ilişkilidir; genellikle hiperpigmentasyon, hiponatremi ve hiperkalemi beklenir. Bu hastada kortizolün korunması ve potasyumun düşük olması kortizol eksikliğinden çok mineralokortikoid fazlalığıyla uyumludur.",
      "ADH fazlalığına bağlı serbest su tutulumu ve dilüsyonel hiponatremi": "ADH fazlalığı serbest su tutulumu yaparak hiponatremi ve düşük serum osmolalitesi oluşturur; potasyum kaybını ve metabolik alkalozu temel olarak açıklamaz. Bu olguda sodyum yüksek-normal, renin baskılı ve aldosteron yüksek olduğundan ana eksen ADH değil mineralokortikoid etkidir.",
      "11β-hidroksilaz blokajına bağlı DOC aracılı mineralokortikoid etki": "11β-hidroksilaz blokajında deoksikortikosteron artışı mineralokortikoid etki oluşturabilir; ancak bu tabloda aldosteron çoğu kez baskılanır ve androjen fazlalığı bulguları eşlik eder. Hastada doğrudan aldosteron yüksekliği ve renin baskılanması primer aldosteron üretimini daha uygun hale getirir."
