          "Primer PTH azalmasına bağlı renal kalsiyum geri emiliminin azalması": "Primer PTH azalması hipokalsemi ve hiperfosfatemi yapmaya eğilimlidir; ayrıca PTH düzeyi düşük veya uygunsuz normal olurdu. Bu hastada PTH yüksek olduğu için paratiroid yanıtı korunmuş ve sekonder olarak artmıştır.",
