      "question": "Bu hastada ilk potasyum sonucunu en iyi açıklayan laboratuvar-biyokimya mekanizması hangisidir?",
      "explanation": "İlk serum örneğinde yüksek potasyum, yüksek hemoliz indeksi ve normal tekrar plazma potasyumu birlikte preanalitik örnek etkisini düşündüren bir uyumsuzluk oluşturur.",
