        "optionComparison": {
          "İn vitro hemolize bağlı hücre içi potasyumun serum örneğine geçmesi": "Bu seçenek ilk örnekte yüksek potasyum, yüksek hemoliz indeksi, normal EKG ve tekrar plazma potasyumunun normal gelmesini birlikte açıklar. Eritrosit içi potasyum yüksek olduğundan örnek alımı veya taşıma sırasında hücre parçalanması serum potasyumunu hastada gerçek hiperkalemi olmadan yükseltebilir.",
          "Metabolik asidoza bağlı potasyumun hücre dışına kayması": "Metabolik asidoz potasyumun hücre dışına kaymasına katkı sağlayabilir; bu durumda kan gazında düşük pH ve düşük bikarbonat beklenirdi. Bu olguda pH ve HCO₃⁻ normal olduğu için potasyum artışını asit-baz kayması açıklamaz.",
          "Aldosteron eksikliğine bağlı renal potasyum atılımının azalması": "Aldosteron eksikliğinde böbrekten potasyum atılımı azalır; hiperkalemiye hipotansiyon, hiponatremi veya düşük aldosteron-kortizol bulguları eşlik edebilir. Hastanın kan basıncı, böbrek fonksiyonu ve tekrar potasyumu normal olduğundan gerçek renal potasyum retansiyonu desteklenmez.",
          "Doku yıkımına bağlı sistemik potasyum salınımının artması": "Rabdomiyoliz veya tümör lizisi gibi doku yıkımı gerçek potasyum salınımı, yüksek CK, fosfat/ürik asit artışı ve klinik bağlamla beklenir. Bu hastada CK ve böbrek fonksiyonu normal, tekrar örnekte potasyum normal olduğu için sistemik doku yıkımı olası değildir.",
          "İnsülin eksikliğine bağlı hücresel potasyum alımının azalması": "İnsülin eksikliği potasyumun hücre içine girişini azaltabilir ve diyabetik ketoasidozda hiperkalemi oluşturabilir. Bu olguda glukoz ve kan gazı normal, keton negatif ve tekrar potasyum normal olduğu için hücresel alım bozukluğu yerine örnek kaynaklı fark ön plandadır."
        },
