          "İnsülin artışıyla fosfat, potasyum ve magnezyumun hücre içine kayması": "Bu seçenek vakadaki beslenme desteği sonrası gelişen hipofosfatemi, hipokalemi ve hipomagnezemiyi aynı biyokimyasal mekanizmaya bağlar. Uzamış açlık sonrası karbonhidrat alımı insülini artırır; glukozun hücre içine girişiyle birlikte fosfat ATP/glikoliz için, potasyum ve magnezyum ise hücre içi bölmeye kayar.",
          "Aldosteron artışıyla izole renal potasyum atılımının hızlanması": "Aldosteron fazlalığı potasyum ve hidrojen iyonu kaybıyla hipokalemik metabolik alkaloz oluşturabilir. Bu olguda fosfat ve magnezyumun da belirgin düşmesi, ayrıca bikarbonatın normal kalması izole mineralokortikoid etkiden çok yeniden beslenme ilişkili hücre içi kaymayı destekler.",
