          "Laktat üretiminin artmasıyla yüksek anyon açıklıklı asidoz gelişmesi": "Laktat artışı yüksek anyon açıklıklı metabolik asidoz yapabilir ve doku hipoksisi veya mitokondriyal oksidasyon sorunlarında beklenir. Bu vakada pH ve bikarbonat normal sınırlardadır; asidoz yerine kas güçsüzlüğü ve ritim duyarlılığı yaratan fosfat-magnezyum-potasyum düşüşü öne çıkmaktadır."
